from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]; colors=set()
        for y,x in q:
          comp.append((y,x))
          if grid[y][x]>1: colors.add(grid[y][x])
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen:
              seen.add((ny,nx)); q.append((ny,nx))
        if len(colors)==1:
          color=next(iter(colors)); cs=set(comp)
          for y,x in comp:
            if all((y+dy,x+dx) in cs for dy in (-1,0,1) for dx in (-1,0,1)):
              out[y][x]=color
    return out

import re

def get_grids(text):
    # extract all pair sections
    pairs=[]
    for m in re.finditer(r'Demo pair \d+ input \(\d+x\d+\):\n(.*?)\nDemo pair \d+ output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance|\Z)',text,re.S):
        parse=lambda s:[[int(v) for v in line.split()] for line in s.strip().splitlines()]
        pairs.append((parse(m.group(1)),parse(m.group(2))))
    return pairs
